CALLS = []


def mark(tag="called"):
    """What every payload in these tests tries to run. It only records that it was called."""
    CALLS.append(tag)
    return tag


class Bomb:
    """Pickles into a call of `mark`: loading the pickle is what runs it."""

    def __init__(self, tag="pickle"):
        self.tag = tag

    def __reduce__(self):
        return (mark, (self.tag,))


