        for expr, want in [("1+2*3", 7), ("(1+2)*3", 9), ("7//2", 3), ("-3 % 5", 2), ("2**-1", 0.5), ("1/2", 0.5), ("2**100", 2 ** 100), (" 4 ", 4), ("-(-3)", 3), ("+5", 5), ("1_000 * 2", 2000),
